    maxrun=1; cur=1
    for i in range(1,len(cmds)):
        if cmds[i]==cmds[i-1] and cmds[i][0]=='bash' and cmds[i][1]:
            cur+=1; maxrun=max(maxrun,cur)
        else: cur=1
